// Which game's catalog defines it.
enum Games : uint8_t { kMain = 1, kSeparateWays = 2, kMercenaries = 4 };
// ItemIDDefine's classifiers, as bits.
enum Flags : uint16_t {
  kFJewelItem = 1 << 0,
  kFCharm = 1 << 1,
  kFCraftRecipe = 1 << 2,
  kFTreasureMap = 1 << 3,
  kFAttacheCase = 1 << 4,
  kFAttacheCaseSkin = 1 << 5,
  kFArmor = 1 << 6,
  kFToken = 1 << 7,
  kFKnife = 1 << 8,
};

struct Def {
  int32_t id;           // chainsaw.ItemID
  const char* name;     // the English game's ("" for one the game never names)
  uint8_t type;         // chainsaw.ItemType
  uint8_t bank, group;  // the panel's filing
  uint8_t offered;      // the panel's add lists offer it
  uint8_t games;        // Games
  uint8_t dlc;          // a DLC's catalog defines it
  uint8_t w, h;         // its piece in the attache case: columns, rows (ItemSizeKind)
  int32_t stack;        // how many one piece (or one entry off the grid) holds: _StackMax
  int16_t durability;   // a knife's: _DefaultDurabilityMax
  int16_t ammo;         // a gun's magazine: _AmmoMax
  int16_t weapon;       // chainsaw.WeaponID (-1: not a weapon)
  uint16_t flags;       // Flags
  int16_t rank;         // its place in the panel's lists
};

