inline const Def* find(int32_t id) {
  int lo = 0, hi = kCount - 1;
  while (lo <= hi) {
    const int mid = (lo + hi) / 2;
    if (kItems[mid].id == id) return &kItems[mid];
    if (kItems[mid].id < id) lo = mid + 1;
    else hi = mid - 1;
  }
  return nullptr;
}
inline int index_of(int32_t id) {
  const Def* d = find(id);
  return d ? static_cast<int>(d - kItems) : -1;
}
inline const char* name(int32_t id) {
  const Def* d = find(id);
  return d && d->name[0] ? d->name : "";
}
// Takes room in the attache case (has a piece on its grid).
inline bool in_case(int32_t id) {
  const Def* d = find(id);
  return d && d->bank < kCaseBanks && d->w;
}
// A weapon with a state of its own - a gun's rounds and upgrades, a knife's durability: one
// piece each, never stacked.
inline bool keeps_state(int32_t id) {
  const Def* d = find(id);
  return d && d->weapon >= 0 && (d->type == kGun || d->type == kMelee);
}

